#!/usr/bin/env python3
"""Reproduce third-party notices from locked package sources (Python 3.11+).

Run after `npm ci --prefix devcel-studio` and `cargo fetch --locked`.
--check compares every generated byte; --check-locks is an offline build gate.
Never synthesizes license text from an SPDX label.
"""
from __future__ import annotations
import argparse, hashlib, html, json, re, subprocess, sys, tomllib
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
LICENSE_NAME = re.compile(r'(?i)^(licen[sc]es?|notices?|copying|copyright|authors|unlicense|patents?)([._-]|$)')
EMBEDDED_SOURCE = re.compile(r'^embedded-notices/(.+)\.L([1-9][0-9]*)\.COPYRIGHT$')

def digest(data): return hashlib.sha256(data).hexdigest()
def read_json(path): return json.loads(path.read_text(encoding='utf-8'))

def cargo_metadata(repo):
    # Cargo's JSON is UTF-8, irrespective of the Windows process code page.
    return json.loads(subprocess.check_output(
        ['cargo', 'metadata', '--locked', '--format-version', '1'],
        cwd=repo, text=True, encoding='utf-8', errors='strict'))

def embedded_source_identity(entry, original, body_hash):
    """Bind an embedded notice to its original source without publishing a path label.

    Package-relative source paths are inputs to the identity, never rewritten in
    the source or license body. Repeating the same source reference intentionally
    produces the same ID, even when it is included by more than one lockfile.
    """
    match = EMBEDDED_SOURCE.fullmatch(original['path'])
    if not match: return None
    identity = {
        'ecosystem': entry['ecosystem'],
        'package': entry['name'],
        'version': entry['version'],
        'source_url': original.get('url') or original.get('source') or entry.get('source') or entry.get('bundled_from', {}).get('source'),
        'original_path': match[1],
        'original_line': int(match[2]),
        'body_sha256': body_hash,
    }
    canonical = json.dumps(identity, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    return f'embedded-notices/source-sha256-{digest(canonical)}.COPYRIGHT', canonical

def lock_hashes(repo):
    # Resolve both sides before containment checks (Windows short/long temp paths
    # and symlinked worktrees can otherwise describe the same root differently).
    repo = repo.resolve()
    paths = ['scripts/generate-third-party-notices.py', 'scripts/license_evidence.py', 'scripts/npm_license_inventory.py', 'scripts/embedded_license_notices.py', 'Cargo.lock', 'package-lock.json', 'devcel-studio/package-lock.json',
             'third-party/assets.json', 'third-party/preferred-sources.json', 'third-party/cargo-upstream.json', 'third-party/npm-upstream.json', 'third-party/npm-license-declarations.json',
             'rust-toolchain.toml', 'third-party/rust-standard-library.json', 'Cargo.toml', 'devcel-core/Cargo.toml', 'devcel-cli/Cargo.toml', 'devcel-runtime/Cargo.toml',
             'devcel-studio/src-tauri/Cargo.toml', 'package.json', 'devcel-studio/package.json',
             'devcel-studio/templates/plugin-template/package.json',
             'devcel-studio/templates/plugin-template/LICENSE',
             'devcel-studio/src/lib/react-data-grid/package.json',
             'devcel-studio/src/lib/drei-background/provenance.json']
    paths += ['LICENSE-NOTICE', 'devcel-core/LICENSE', 'devcel-cli/LICENSE', 'devcel-runtime/LICENSE', 'devcel-studio/LICENSE']
    paths += [p.relative_to(repo).as_posix() for p in sorted((repo/'importers').glob('*/LICENSE'))]
    paths += [p.relative_to(repo).as_posix() for p in sorted((repo/'importers').glob('*/package.json'))]
    if (repo/'third-party/assets.json').is_file():
        for asset in read_json(repo/'third-party/assets.json').get('assets', []):
            for item in asset.get('license_files', []):
                path=item['path'] if isinstance(item,dict) else item
                if not (repo/path).resolve().is_relative_to(repo): raise RuntimeError('Asset license path escapes repository')
                paths.append(path)
    paths += [p.relative_to(repo).as_posix() for p in sorted((repo/'third-party/upstream').rglob('*')) if p.is_file()]
    # Build metadata/source hashes ignore checkout CRLF only. Legal evidence
    # uses authenticated original bytes, including its original line endings.
    upstream = {e['path']: e for e in all_upstream_evidence(repo)}
    def input_bytes(path):
        if path in upstream:
            return authenticated_upstream_bytes(repo, upstream[path])
        raw = (repo/path).read_bytes()
        is_source = (path.endswith(('.py', '.json', '.toml')) or path == 'Cargo.lock')
        if is_source and not path.startswith('third-party/upstream/'):
            return raw.replace(b'\r\n', b'\n')
        return raw
    return {p: digest(input_bytes(p)) for p in paths if (repo/p).exists()}

def authenticated_upstream_bytes(repo, evidence):
    from license_evidence import authenticated_text_bytes
    try:
        return authenticated_text_bytes((repo/evidence['path']).read_bytes(), evidence.get('sha256'), evidence['path'])
    except ValueError as error:
        raise RuntimeError(str(error)) from error


def upstream_evidence(repo):
    path = repo/'third-party/cargo-upstream.json'
    return read_json(path) if path.exists() else {}


def all_upstream_evidence(repo):
    entries = []
    for filename in ('cargo-upstream.json', 'npm-upstream.json'):
        path = repo/'third-party'/filename
        if path.exists():
            entries.extend(e for items in read_json(path).values() for e in items)
    toolchain = repo/'third-party/rust-standard-library.json'
    if toolchain.exists():
        entries.extend(read_json(toolchain).get('license_files', []))
    assets = repo/'third-party/assets.json'
    if assets.exists():
        entries.extend(item for asset in read_json(assets).get('assets', [])
                       for item in asset.get('license_files', []) if isinstance(item, dict))
    return entries


def verify_upstream(repo):
    for evidence in all_upstream_evidence(repo):
        authenticated_upstream_bytes(repo, evidence)
    return upstream_evidence(repo)


def cargo_inventory(repo, metadata):
    nodes = {n['id']: n for n in metadata['resolve']['nodes']}
    packages = {p['id']: p for p in metadata['packages']}
    scopes = {}
    for root in ('devcel-studio', 'devcel-cli', 'devcel-runtime', 'devcel-core'):
        pending = [p['id'] for p in metadata['packages'] if not p.get('source') and p['name'] == root]
        seen = set()
        while pending:
            current = pending.pop()
            if current in seen: continue
            seen.add(current)
            # All target-specific normal edges are included, conservatively.
            for dep in nodes.get(current, {}).get('deps', []):
                if any(k['kind'] is None for k in dep['dep_kinds']): pending.append(dep['pkg'])
        scopes[root] = seen
    upstream = verify_upstream(repo)
    lock = {(p['name'], p['version']):p for p in tomllib.loads((repo/'Cargo.lock').read_text())['package']}
    output = []
    for p in metadata['packages']:
        if not p.get('source'): continue
        base = Path(p['manifest_path']).parent
        files = sorted(f for f in base.rglob('*') if f.is_file() and (LICENSE_NAME.match(f.name) or any(part.lower() in ('licenses', 'licences', 'legal', 'notices') for part in f.relative_to(base).parts[:-1])))
        if p.get('license_file'):
            explicit = Path(p['license_file'])
            if not explicit.is_absolute(): explicit = base/explicit
            if explicit.is_file() and explicit not in files: files.append(explicit)
        texts = [{'path':f.relative_to(base).as_posix(), 'text':f.read_bytes().decode('utf-8', errors='strict')} for f in files]
        for evidence in upstream.get(f'{p["name"]}@{p["version"]}', []):
            texts.append({'path':evidence['path'], 'text':authenticated_upstream_bytes(repo, evidence).decode('utf-8'), 'url':evidence['url'], 'note':evidence.get('note')})
        errors=[]
        if not texts: errors.append('No original license text found in crate or reviewed upstream evidence')
        if not p.get('license'): errors.append('Missing license expression')
        expression=p.get('license') or 'UNKNOWN'
        selection = 'MIT' if 'AND' not in expression and (expression == 'MIT' or ' OR ' in expression) and re.search(r'(?<![A-Za-z-])MIT(?![A-Za-z-])', expression) else expression
        review = []
        if '/' in expression: review.append('legacy-license-expression: all declared license texts retained; no OR choice inferred')
        if 'MPL-' in selection or 'GPL-' in selection: review.append('copyleft-source-obligations')
        if p.get('repository') == 'https://github.com/madsmtm/objc2': review.append('upstream-Apple-SDK-licensing-caveat')
        output.append({'ecosystem':'cargo','name':p['name'],'version':p['version'],
            'license':expression,'license_selection':selection,
            'selection_basis':'MIT is an expressly offered alternative; original expression and all supplied texts retained' if selection != expression else 'Original terms retained',
            'authors':p.get('authors',[]),'review':review,'source':p['source'],'repository':p.get('repository'),
            'checksum':lock[(p['name'],p['version'])].get('checksum'),
            'scope':[root for root, ids in scopes.items() if p['id'] in ids] or ['build-or-test-only'],
            'texts':texts,'errors':errors})
    return output

def devcel_component_inventory(repo, metadata):
    result=[]
    for package in metadata['packages']:
        if package.get('source'): continue
        path=Path(package['manifest_path']).parent/'LICENSE'
        # Studio's Cargo crate lives one directory below its component license.
        if package['name']=='devcel-studio': path=path.parent.parent/'LICENSE'
        if not path.is_file(): raise RuntimeError('Missing Devcel component license: ' + package['name'])
        result.append({'ecosystem':'devcel','name':package['name'],
            'license':package.get('license') or 'UNKNOWN','source':'Workspace source at the matching release commit; see SOURCE-ACCESS.json on the Release page',
            'scope':[package['name']],'texts':[{'path':package['name']+'/LICENSE','text':path.read_bytes().decode('utf-8')}],
            'errors':[] if package.get('license') else ['Missing component license declaration']})
    return result

def importer_inventory(repo):
    result=[]
    for path in sorted((repo/'importers').glob('*/LICENSE')):
        name='devcel-'+path.parent.name
        result.append({'ecosystem':'devcel','name':name,
            'license':'MIT','source':'Devcel engine SDK source at the matching release commit; see SOURCE-ACCESS.json',
            'scope':[name],'texts':[{'path':path.relative_to(repo).as_posix(),'text':path.read_bytes().decode('utf-8')}], 'errors':[]})
    return result

def asset_inventory(repo):
    manifest=repo/'third-party/assets.json'
    if not manifest.exists(): return []
    output=[]
    for asset in read_json(manifest).get('assets',[]):
        texts=[]
        for item in asset.get('license_files',[]):
            path=item['path'] if isinstance(item,dict) else item
            raw = authenticated_upstream_bytes(repo, item) if isinstance(item,dict) else (repo/path).read_bytes()
            texts.append({'path':path,'text':raw.decode('utf-8')})
        output.append({'ecosystem':'asset','name':asset.get('name',asset['id']),
            'version':asset.get('version') or 'vendored','license':asset.get('license') or 'UNKNOWN',
            'source':asset.get('upstream'),'scope':asset.get('paths',[]),'distribution':asset.get('distribution'),
            'evidence':asset.get('evidence'),'notes':asset.get('notes'), 'texts':texts,
            'errors':[] if texts and asset.get('status') not in ('unknown','unresolved') else ['Unresolved vendored license evidence']})
    return output

def rust_standard_library_inventory(repo):
    manifest = read_json(repo/'third-party/rust-standard-library.json')
    pinned = tomllib.loads((repo/'rust-toolchain.toml').read_text())['toolchain']['channel']
    if manifest['rust_version'] != pinned:
        raise RuntimeError('Rust standard-library notices do not match the pinned toolchain')
    texts=[]
    for evidence in manifest['license_files']:
        raw = authenticated_upstream_bytes(repo, evidence)
        texts.append({'path':evidence['path'],'text':raw.decode('utf-8'),'source':evidence['source']})
    return [{'ecosystem':'toolchain','name':'Rust standard library','version':manifest['rust_version'],
             'license':manifest['license'],'license_selection':'MIT',
             'source':manifest['source'],'scope':['devcel-studio','devcel-cli','devcel-runtime'],
             'notes':manifest['notes'],'texts':texts,'errors':[]}]

def render(repo, entries, hashes, include_templates=True):
    source_identities={}
    files={}; inventory=[]; chunks=['Devcel — Third-party software notices\n\nOriginal Devcel component licenses and third-party license/attribution texts are reproduced below. Package scope is conservative: runtime dependencies can include code eliminated by the bundler/linker. Build/test-only packages are recorded separately in inventory.json. License choices are recorded in inventory.json; all supplied alternative texts are retained. Source access: use the matching version Release page and SOURCE-ACCESS.json for exact commit source, rebuild instructions and preferred dependency sources. Every binary recipient must have equivalent source access; do not redistribute using inaccessible private links.\n']
    for entry in sorted(entries,key=lambda p:(p['ecosystem'],p['name'],p.get('version', ''),str(p.get('source')))):
        item={k:v for k,v in entry.items() if k not in ('texts','evidence_origin','integrity_verified')}; item['texts']=[]
        version = f" {item['version']}" if 'version' in item else ''
        chunks.append(f'\n{"="*78}\n{item["ecosystem"]}: {item["name"]}{version}\nLicense: {item["license"]}\nSource: {item.get("source")}\nScope: {json.dumps(item.get("scope"),ensure_ascii=False)}\n')
        for original in entry['texts']:
            raw=original['text'].encode('utf-8'); path=f'licenses/{digest(raw)}.txt'; files[path]=raw
            evidence={k:v for k,v in original.items() if k!='text'}; evidence.update({'file':path,'sha256':digest(raw)})
            identity=embedded_source_identity(entry, original, evidence['sha256'])
            if identity is not None:
                source_label, canonical=identity
                if source_label in source_identities and source_identities[source_label] != canonical:
                    raise RuntimeError('Embedded notice source identity collision')
                source_identities[source_label]=canonical
                evidence['path']=source_label
            item['texts'].append(evidence)
            label = (('Source: ' + original['url'] + '\n') if original.get('url') else '') + (('Evidence: ' + original['note'] + '\n') if original.get('note') else '')
            chunks.append(f'\n--- {evidence["path"]} ---\n{label}{original["text"]}\n')
        if entry.get('errors'): chunks.append('UNRESOLVED: '+'; '.join(entry['errors'])+'\n')
        inventory.append(item)
    template=repo/'devcel-studio/templates/plugin-template/package.json'
    templates=[]
    if include_templates and template.is_file():
        manifest=read_json(template)
        templates.append({'path':template.relative_to(repo).as_posix(),'scope':'downstream-template-manifest-only; dependency code is not bundled by this manifest',
            'license':manifest.get('license'),'peerDependencies':manifest.get('peerDependencies',{}),'devDependencies':manifest.get('devDependencies',{}),'dependencies':manifest.get('dependencies',{})})
    document={'schema_version':1,'inputs':hashes,'templates':templates,'packages':inventory}
    files['inventory.json']=(json.dumps(document,indent=2,ensure_ascii=False)+'\n').encode()
    files['THIRD-PARTY-NOTICES.txt']=''.join(chunks).encode()
    return files

def verify_locks(repo):
    path=repo/'third-party/generated/inventory.json'
    if not path.is_file(): raise RuntimeError('Missing third-party inventory; regenerate notices')
    manifest=read_json(path)
    if manifest['inputs'] != lock_hashes(repo): raise RuntimeError('Third-party inventory is stale; regenerate notices')
    # Each shared body is read once per verification, but every reference is checked.
    evidence_hashes = {}
    for package in manifest['packages']:
        if package.get('errors'): raise RuntimeError(f'Unresolved license: {package["name"]}: {package["errors"]}')
        for text in package['texts']:
            path=repo/'third-party/generated'/text['file']
            if path not in evidence_hashes:
                if not path.is_file(): raise RuntimeError(f'License text changed or missing: {path}')
                evidence_hashes[path] = digest(path.read_bytes())
            if evidence_hashes[path]!=text['sha256']: raise RuntimeError(f'License text changed or missing: {path}')
    expected=(repo/'third-party/generated/THIRD-PARTY-NOTICES.txt').read_bytes()
    if (repo/'devcel-studio/public/legal/THIRD-PARTY-NOTICES.txt').read_bytes()!=expected: raise RuntimeError('Studio notice copy is stale')
    from legal_distribution import distribution_files
    distribution_files(repo/'third-party/generated')
    print(f'License evidence verified: {len(manifest["packages"])} packages')

def verify_render(root):
    import copy
    GENERATED = "third-party/generated"
    PUBLIC = "devcel-studio/public/legal/THIRD-PARTY-NOTICES.txt"
    """Recover render inputs, never guess or replace text inside legal bodies."""
    verify_locks(root)
    document = json.loads((root/GENERATED/'inventory.json').read_bytes())
    entries = copy.deepcopy(document['packages'])
    generated_root = (root/GENERATED).resolve()
    evidence_bytes = {}
    for entry in entries:
        for evidence in entry['texts']:
            relative = Path(evidence['file'])
            path = root/GENERATED/relative
            if relative not in evidence_bytes:
                if relative.is_absolute() or not path.resolve().is_relative_to(generated_root):
                    raise ValueError('License evidence escapes generated directory')
                raw = path.read_bytes()
                evidence_bytes[relative] = (raw, digest(raw))
            raw, actual_hash = evidence_bytes[relative]
            if actual_hash != evidence['sha256']:
                raise ValueError('License evidence hash mismatch')
            evidence.pop('file')
            evidence.pop('sha256')
            # Already-hashed embedded source identities are deliberately retained.
            evidence['text'] = raw.decode('utf-8')
    rendered = render(root, entries, document['inputs'])
    actual = {p.relative_to(root/GENERATED).as_posix(): p.read_bytes()
              for p in (root/GENERATED).rglob('*') if p.is_file()}
    if rendered != actual or (root/PUBLIC).read_bytes() != rendered['THIRD-PARTY-NOTICES.txt']:
        raise ValueError('Reviewed notice render round-trip differs; regenerate and review first')
    return entries


def generate(repo=REPO, *, check=False, ensure=False, metadata=None):
    repo = Path(repo).resolve()
    if ensure:
        try:
            verify_locks(repo)
            return
        except (OSError, ValueError, RuntimeError, KeyError):
            pass
    if (repo/'third-party/generated').is_symlink() or (repo/'devcel-studio/public/legal/THIRD-PARTY-NOTICES.txt').is_symlink():
        raise RuntimeError('Refusing linked generated notice output')
    metadata = metadata if metadata is not None else cargo_metadata(repo)
    from npm_license_inventory import collect
    entries=cargo_inventory(repo,metadata)+devcel_component_inventory(repo,metadata)+importer_inventory(repo)+collect(repo)+asset_inventory(repo)+rust_standard_library_inventory(repo)
    for entry in entries: entry.setdefault('ecosystem','npm')
    unresolved=[entry['name']+': '+str(entry['errors']) for entry in entries if entry.get('errors')]
    if unresolved:
        print('\n'.join(unresolved), file=sys.stderr)
        raise RuntimeError('Unresolved license evidence; generated output was not changed')
    files=render(repo,entries,lock_hashes(repo));output=repo/'third-party/generated'
    expected={output/name:data for name,data in files.items()}
    expected[repo/'devcel-studio/public/legal/THIRD-PARTY-NOTICES.txt']=files['THIRD-PARTY-NOTICES.txt']
    changed=[]
    for path,data in expected.items():
        if not path.is_file() or path.read_bytes()!=data:
            changed.append(str(path.relative_to(repo)))
            if not check:path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
    if output.exists():
        for path in output.rglob('*'):
            if path.is_file() and path not in expected:
                changed.append(str(path.relative_to(repo)))
                if not check:path.unlink()
    unresolved=[e['name'] + (f"@{e['version']}" if 'version' in e else '') + f": {e['errors']}" for e in entries if e.get('errors')]
    print(f'{len(entries)} packages; {len(changed)} changed files; {len(unresolved)} unresolved')
    if unresolved: print('\n'.join(unresolved),file=sys.stderr)
    if unresolved or (check and changed): raise RuntimeError('License generation failed or generated output differs')
    verify_locks(repo)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument('--check', action='store_true')
    mode.add_argument('--check-locks', action='store_true')
    mode.add_argument('--ensure', action='store_true', help='Generate missing/stale build outputs from authenticated locked sources')
    parser.add_argument('--repo', type=Path, default=REPO)
    parser.add_argument('--metadata', type=Path, help='Previously generated cargo metadata, for diagnostics only')
    args = parser.parse_args()
    if args.check_locks:
        verify_locks(args.repo.resolve())
    else:
        try:
            generate(args.repo, check=args.check, ensure=args.ensure,
                     metadata=read_json(args.metadata) if args.metadata else None)
        except RuntimeError as error:
            parser.exit(1, str(error)+'\n')


if __name__ == '__main__':
    main()
